#!/bin/bash
# IMAGE.XZ mode test: real XZ decompression, shimmed losetup/mount.
# The "loop device" is inert real node /dev/loop0; NO real loop attach or
# mount happens.
set -u
HERE=$(cd "$(dirname "$0")" && pwd)
P=$(cd "$HERE/.." && pwd)/pi_clean.sh
# shared rootfs fixture (regenerated by make_base_fix.sh when missing)
[[ -e /tmp/pi_clean_test/base_fix/etc/os-release ]] || bash "$HERE/make_base_fix.sh"
SHIM=/tmp/pi_clean_test/shim_loop
LOG=/tmp/pi_clean_test/shim_loop.log
export SHIM_LOG="$LOG"
D=/tmp/pi_clean_test/xz
rm -rf "$D"; mkdir -p "$D"

# fixtures: a plausible xz-compressed image (any payload), plus a corrupt one
tar -C /tmp/pi_clean_test -cf - base_fix 2>/dev/null | xz -c > "$D/image.img.xz"
cp "$D/image.img.xz" "$D/raw.img"          # no .xz extension -> magic path
printf 'garbage not xz' > "$D/corrupt.img.xz"

rm -rf "$SHIM"; mkdir -p "$SHIM"
STAGE=/tmp/pi_clean_test/dev_stage
rm -rf "$STAGE"; mkdir -p "$STAGE"
cp -a /tmp/pi_clean_test/base_fix/. "$STAGE/"
: > "$LOG"

cat > "$SHIM/losetup" <<'EOF'
#!/bin/bash
echo "losetup $*" >> "${SHIM_LOG:?}"
case $* in -d*) exit 0 ;; esac
[[ -n ${SHIM_FAILALL:-} ]] && exit 1
echo /dev/loop0
EOF
cat > "$SHIM/mount" <<'EOF'
#!/bin/bash
dev=$3; mp=$4
[[ $dev == /dev/loop0 ]] || exit 32
cp -a ${SHIM_STAGE}/. "$mp/"
exit 0
EOF
# emulate a REAL umount: the "filesystem" (the staged content the sim
# `mount` copied into the mount point) comes off; the mount-point dir
# itself stays (as with a real umount) so the script's rmdir succeeds
cat > "$SHIM/umount" <<'EOF'
#!/bin/bash
mp=${1:-}
# GNU rm refuses "dir/." — find -delete empties the dir, keeps the dir itself
[[ -n $mp && -d $mp ]] && find "$mp" -mindepth 1 -delete 2>/dev/null
exit 0
EOF
export SHIM_STAGE="$STAGE"
chmod +x "$SHIM/losetup" "$SHIM/mount" "$SHIM/umount"

t() { desc=$1; want=$2; shift 2
    out=$(PATH="$SHIM:$PATH" "$@" 2>&1); rc=$?
    if [[ $rc == "$want" ]]; then echo "PASS (rc=$rc): $desc"; else echo "FAIL (rc=$rc want=$want): $desc"; printf '%s\n' "$out" | head -6; return 1; fi
}
noextracts() {
    local l; l=$(ls /dev/shm/pi_clean.* /tmp/pi_clean.* "$D"/pi_clean.* 2>/dev/null)
    if [[ -n $l ]]; then echo "FAIL: extract left behind: $l"; return 1; fi
    echo "PASS: no extract left behind"
}

echo B=xz-extension;    t "-t on a .img.xz"          0 bash "$P" "$D/image.img.xz" -t
tot=$(PATH="$SHIM:$PATH" bash "$P" "$D/image.img.xz" -t 2>/dev/null)
[[ "$tot" == "2097162" ]] && echo "PASS: -t number (xz) ($tot)" || echo "FAIL: -t number (xz) ($tot)"
note=$(PATH="$SHIM:$PATH" bash "$P" "$D/image.img.xz" -t 2>&1 >/dev/null)
[[ "$note" == *"extracting to RAM: "* ]] && echo "PASS: xz extract went to RAM" \
    || { echo "FAIL: no RAM note for xz: $note"; }
[[ "$note" == *"decompressing"*"can take a while"* && "$note" == *"extracted to "* ]] \
    && echo "PASS: extraction announced (start + done)" \
    || { echo "FAIL: no extraction announcement: $note"; }
noextracts

echo C=xz-magic-no-ext; t "-t on xz named raw.img"    0 bash "$P" "$D/raw.img" -t
tot=$(PATH="$SHIM:$PATH" bash "$P" "$D/raw.img" -t 2>/dev/null)
[[ "$tot" == "2097162" ]] && echo "PASS: -t number (magic) ($tot)" || echo "FAIL: -t number (magic) ($tot)"
noextracts

echo D=corrupt-xz
out=$(PATH="$SHIM:$PATH" bash "$P" "$D/corrupt.img.xz" -t 2>&1); rc=$?
if [[ $rc == 2 && $out == *"extracting"*"failed"* ]]; then echo "PASS (rc=$rc): corrupt xz -> clean failure"
else echo "FAIL (rc=$rc): corrupt xz: $out" | tr '\n' ' '; echo; fi
noextracts

echo E=xz-attach-fail
out=$(env SHIM_FAILALL=1 PATH="$SHIM:$PATH" bash "$P" "$D/image.img.xz" -t 2>&1); rc=$?
if [[ $rc == 2 && $out == *"cannot attach"* ]]; then echo "PASS (rc=$rc): attach failure with .xz"
else echo "FAIL (rc=$rc): attach failure (xz): $out" | tr '\n' ' '; echo; fi
noextracts

grep -q '^losetup -d /dev/loop0$' "$LOG" && echo "PASS: loop detached on exit" || { echo "FAIL: no detach:"; cat "$LOG"; }
left=$(ls -d /run/pi_clean.* /tmp/pi_clean.* 2>/dev/null)
if [[ -z $left ]]; then echo "PASS: no leftover mount points"
else echo "shim leftovers (expected): $left" | tr '\n' ' '; echo; rm -rf $left; fi
